ALTER TABLE public.quote_requests ADD COLUMN revision integer NOT NULL DEFAULT 1, ADD COLUMN submission_hash text, ADD COLUMN notion_page_id text, ADD COLUMN notion_status text NOT NULL DEFAULT 'pending', ADD COLUMN notion_error text, ADD COLUMN notion_revision integer NOT NULL DEFAULT 0, ADD COLUMN dispatch_token uuid, ADD COLUMN dispatch_until timestamptz, ADD COLUMN dispatch_attempts integer NOT NULL DEFAULT 0, ADD COLUMN email_provider_id text;
CREATE OR REPLACE FUNCTION public.reservation_save(p_key text,p_hash text,p_row jsonb) RETURNS public.quote_requests LANGUAGE plpgsql SET search_path=public AS $$ DECLARE r public.quote_requests; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(p_key,0)); SELECT * INTO r FROM public.quote_requests WHERE idempotency_key=p_key; IF FOUND THEN IF r.submission_hash IS DISTINCT FROM p_hash THEN RAISE EXCEPTION 'idempotency_conflict'; END IF; RETURN r; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(p_row->>'ip_hash',1)); IF (SELECT count(*) FROM public.quote_requests WHERE ip_hash=p_row->>'ip_hash' AND created_at>now()-interval '1 hour')>=5 THEN RAISE EXCEPTION 'rate_limited'; END IF; INSERT INTO public.quote_requests(reference,idempotency_key,submission_hash,lang,mode,full_name,email,phone,buyer_type,company,billing_tax_id,billing_address,billing_email,needs_invoice,notes,destinations,total_roses,breakdown,needs_review,ip_hash) VALUES('SJ27-'||upper(replace(gen_random_uuid()::text,'-','')),p_key,p_hash,p_row->>'lang',p_row->>'mode',p_row->>'full_name',p_row->>'email',p_row->>'phone','company',p_row->>'company',p_row->>'billing_tax_id',p_row->>'billing_address',p_row->>'billing_email',true,p_row->>'notes',p_row->'destinations',(p_row->>'total_roses')::integer,p_row->'breakdown',(p_row->>'needs_review')::boolean,p_row->>'ip_hash') RETURNING * INTO r; RETURN r; END $$;
REVOKE ALL ON FUNCTION public.reservation_save(text,text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reservation_save(text,text,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.reservation_update(p_id uuid,p_revision integer,p_patch jsonb,p_actor uuid) RETURNS public.quote_requests LANGUAGE plpgsql SET search_path=public AS $$ DECLARE r public.quote_requests; BEGIN IF NOT public.has_billing_role(p_actor) THEN RAISE EXCEPTION 'forbidden'; END IF; SELECT * INTO r FROM public.quote_requests WHERE id=p_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'reservation_missing'; END IF; IF r.revision<>p_revision OR r.dispatch_until>now() THEN RAISE EXCEPTION 'reservation_conflict'; END IF; IF EXISTS(SELECT 1 FROM public.billing_orders WHERE reservation_id=p_id) AND (p_patch->'destinations' IS DISTINCT FROM r.destinations OR p_patch->>'mode' IS DISTINCT FROM r.mode OR (p_patch->>'total_roses')::integer<>r.total_roses) THEN RAISE EXCEPTION 'order_already_prepared'; END IF; UPDATE public.quote_requests SET reservation_status=p_patch->>'reservation_status',mode=p_patch->>'mode',destinations=p_patch->'destinations',total_roses=(p_patch->>'total_roses')::integer,breakdown=p_patch->'breakdown',needs_review=(p_patch->>'needs_review')::boolean,notes=p_patch->>'notes',revision=revision+1,updated_at=now(),notion_status='pending',notion_error=NULL WHERE id=p_id RETURNING * INTO r; INSERT INTO public.billing_audit(actor,action,entity_id,detail) VALUES(p_actor,'reservation_update',p_id,jsonb_build_object('revision',r.revision)); RETURN r; END $$;
REVOKE ALL ON FUNCTION public.reservation_update(uuid,integer,jsonb,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reservation_update(uuid,integer,jsonb,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.reservation_claim(p_id uuid) RETURNS public.quote_requests LANGUAGE plpgsql SET search_path=public AS $$ DECLARE r public.quote_requests; BEGIN UPDATE public.quote_requests SET dispatch_token=gen_random_uuid(),dispatch_until=now()+interval '3 minutes',dispatch_attempts=dispatch_attempts+1 WHERE id=p_id AND (dispatch_until IS NULL OR dispatch_until<now()) RETURNING * INTO r; RETURN r; END $$;
REVOKE ALL ON FUNCTION public.reservation_claim(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reservation_claim(uuid) TO service_role;
CREATE FUNCTION public.grant_reservation_manager() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF lower(NEW.email)='solidaristjordi@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'billing_admin') ON CONFLICT(user_id,role) DO NOTHING; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.grant_reservation_manager() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER reservation_manager_signup AFTER INSERT OR UPDATE OF email_confirmed_at,email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.grant_reservation_manager();